using System.Collections.Concurrent;using OrdersService.Models;namespace OrdersService.Services;public sealed class OrderStore{private readonly ConcurrentDictionary<int,ExamOrder> _items=new();private int _nextId;public IReadOnlyCollection<ExamOrder> GetAll()=>_items.Values.OrderByDescending(x=>x.Id).ToArray();public ExamOrder? Get(int id)=>_items.GetValueOrDefault(id);public ExamOrder Add(CreateOrderRequest r,string subject){var id=Interlocked.Increment(ref _nextId);var item=new ExamOrder(id,r.SubjectId,subject,r.CandidateName.Trim(),r.ExamSession.Trim(),DateTimeOffset.UtcNow);_items[id]=item;return item;}}